ROOT=Path(__file__).resolve().parents[1]
def main():
 dossier=ROOT/'docs/review/2026-10-14';proof=json.loads((dossier/'verification.json').read_text());folder=ROOT/'reports/ontology-review/2026-10-14';folder.mkdir(parents=True,exist_ok=True)
 assert proof['passed'],'Do not publish an unsuccessful acceptance as final'
 pdfmetrics.registerFont(TTFont('Body','/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'));pdfmetrics.registerFont(TTFont('Bold','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'))
 body=ParagraphStyle('Body',fontName='Body',fontSize=10,leading=15,spaceAfter=10);title=ParagraphStyle('Title',parent=body,fontName='Bold',fontSize=22,leading=27,spaceAfter=18);heading=ParagraphStyle('Heading',parent=body,fontName='Bold',fontSize=15,leading=20,spaceAfter=12);small=ParagraphStyle('Small',parent=body,fontSize=9,leading=13,spaceAfter=0)
 def p(text,style=body):return Paragraph(html.escape(text),style)
 def table(headers,rows,widths):
  t=Table([[p(str(x),small) for x in row] for row in [headers]+rows],colWidths=widths,repeatRows=1)
  t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.4,colors.HexColor('#CBD8DF')),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#DCE9EF')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F3F7F9')]),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)]));return t
 story=[p('PROVIDER Ontologie',title),p('Konsolidierung und Echtdatenabnahme | InfAI | 14.10.2026'),p('Modellkandidat 0.3.0-rc2',heading),p('Das Modell deckt die derzeitigen AP2-Datenstrukturen ab. Sein Gesamtumfang ist größer als der empirisch nachgewiesene Bedarf. Deshalb begrenzen eigenständige Fachprofile die benötigte Importmenge; gemeinsame Messwerte und Quellenbelege verbinden die Datenfamilien.'),p('Zielnamespace: https://projekt-provider.de/ontology/'),table(['Prüfbereich','Ergebnis'],[['Begriffe im rc1','905 Klassen/Eigenschaften; 105 durch Beispiele oder Abfragen ausgeübt'],['Regression','42 Tests und 31 Kompetenzfragen erfolgreich'],['Logik','OWL2 DL und HermiT; offizieller BFO2020-Kern lokal gepinnt'],['Echtdaten','GENESIS, CPPI, GEM-Kapazitäten und Comext separat geprüft']],[125,365]),Spacer(1,15),p('Was verbessert wurde',heading),p('Gemeinsames Muster: Ergebnis → Messwert → Wert, Mengenart und Einheit. Quellen, Referenzperiode, Indexbasis, Produktionsumfang und Qualitätsmarker bleiben getrennt. Ergebnisse werden nicht als Beobachtungsaktivitäten behandelt. Fehlende oder geheimhaltungsbedingt unbestimmte Werte werden nicht zu gemessenen Nullen.'),p('Modellumfang',heading),p('Statistik, Maritime, Mining, Events, Supply Chain und BFO sind getrennt wählbar. Nicht ausgeübte Erweiterungen bleiben optional; sie sind nicht automatisch redundant. BFO ist für normale Statistikdaten kein Pflichtimport. Historische Modelle und Prüfberichte bleiben erhalten.'),PageBreak(),p('Abnahme mit vorhandenen Daten',heading),table(['Pilot','Nachgewiesener Ausschnitt','Grenze'],[['GENESIS','1.680 Zellen; 1.102 numerisch; 578 unbestimmt','Drei vorhandene Ausschnitte; keine Anlagenproduktion oder Vintage-Rekonstruktion'],['CPPI','2.212 kombinierte Scores; 806 negativ','Keine automatische kanonische Hafenidentität; Ränge/Komponenten außerhalb der Projektion'],['GEM','20 Quellzeilen; zehn Kapazitätswerte','Begrenzter Mai2026-Ausschnitt; keine tatsächliche Produktion oder ICMM-Verknüpfung'],['Comext','3.960 Zellen; bestehende vollständige Projektion erneut geprüft','Jährliche Warenauswahl und historische Grenzen bleiben qualifiziert']],[65,210,215]),Spacer(1,15),p('Gemeinsame Abfrage',heading),p('queries/common-measurements.rq liest die Messwerte unabhängig von der Datenfamilie aus und gruppiert sie nach Mengenart und Einheit. Sie summiert keine unvereinbaren Größen. Produktionsmenge, enthaltene Stickstoffmasse, Kapazität, Index und Rang dürfen nicht gleichgesetzt werden.'),p('Logische Kontrolle',heading),p('Die vollständige lokale Modellabschlussmenge besteht die OWL2-DL-Profilprüfung und HermiT-Konsistenz/Klassenkohärenz. Positive Proben bestätigen Domain/Range-Folgerungen. Negative Proben erkennen eine widersprüchliche Fehlwertinstanz und eine Klasse, die zugleich BFO-Continuant und Occurrent sein soll.'),p('Prüfgrenze',heading),p('Andere externe Vokabulare sind ausdrücklich deklarierte Referenzen. Es ist keine vollständige PROV-, SOSA- oder GeoSPARQL-Axiomabschlussmenge abgenommen. SHACL prüft Datenprofil, Kardinalitäten und Kalenderlexik. Die technische Kohärenz beweist keine fachliche Wahrheit oder angemessene Detailtiefe aller optionalen Begriffe.'),PageBreak(),p('Rechte, Übergabe und nächste Umsetzung',heading),p('Nutzungsbedingungen bleiben quellenbezogen',heading),p('GENESIS: Datenlizenz Deutschland Namensnennung2.0 laut Erfassungsmanifesten. CPPI: CC BY-NC3.0 IGO, keine pauschale kommerzielle Freigabe. Die Wiederverwendung des lokalen GEM-Workbooks bleibt offen; im Pilot wird keine Lizenz behauptet. Die Ontologiemodule behalten ihre jeweiligen Lizenzen; BFO2020 und das Eventmodul behalten CC BY4.0.'),p('Nachvollziehbare Artefakte',heading),p('docs/ontology-consolidation.md erläutert Entscheidungen, Grenzen und ausführbare Prüfungen. docs/model-profiles.md beschreibt die schlanken Einstiegspunkte. Unter docs/review/2026-10-14/ liegen Begriffsregister, Logikbefunde und JSON-Abnahmen mit Modell-/Quelldatenhashes. Das ZIP-Paket enthält Modell, Abfragen, Werkzeuge und Nachweise; vollständige echte Quell- und Projektionsdaten bleiben lokal.'),p('Nächster Arbeitsblock',heading),p('1. Fachliche Rückmeldung der Partner zu Kompetenzfragen, Ereignisbewertungen, Kapazitätsbasis und benötigten Rollen einholen.'),p('2. Die geprüften Projektionen als reguläre versionierte Konverterverträge in provider-datasets übernehmen.'),p('3. Workflow-Pins gezielt migrieren und Integration am Knowledge Graph prüfen.'),p('4. Kanonische Identitäten und qualifizierte Zuordnungen weiterhin getrennt abnehmen.'),p('Verbindlichkeit',heading),p('Lokaler Kandidat für Abstimmung. Keine automatische Umstellung produktiver Konverter oder Workflows, keine Veröffentlichung und keine formale Partnerabnahme. Die Tests des rc1 bleiben historische Belege für den gesicherten Vorgängerstand.'),p('Technische Quellen',heading),p('ROBOT: robot.obolibrary.org/reason und /validate-profile. BFO2020: github.com/BFO-ontology/BFO-2020, Quellcommit im Reasoner-Lock. W3C SHACL: www.w3.org/TR/shacl/.')]
 def footer(c,doc):c.setFont('Body',8);c.setFillColor(colors.HexColor('#526B78'));c.drawString(48,26,'PROVIDER | InfAI | AP2 | 14.10.2026');c.drawRightString(A4[0]-48,26,str(doc.page))
 target=folder/'PROVIDER_Ontologie_Konsolidierung.pdf';SimpleDocTemplate(str(target),pagesize=A4,leftMargin=48,rightMargin=48,topMargin=42,bottomMargin=42,title='PROVIDER Ontologie: Konsolidierung und Echtdatenabnahme',author='InfAI',invariant=1).build(story,onFirstPage=footer,onLaterPages=footer);print(target)
